// Find a pre-rendered label bitmap by text and font size.
// Returns nullptr if not found.
inline const LabelBitmap* findLabelBitmap(const char* text, uint16_t fontSize) {
  for (int i = 0; i < kLabelBitmapCount; i++) {
    if (kLabelBitmaps[i].fontSize == fontSize && strcmp(kLabelBitmaps[i].text, text) == 0) {
      return &kLabelBitmaps[i];
    }
  }
  return nullptr;
}
